exercises.solution:
cat > ~/bin/lacznosc.sh <<'EOF'
#!/bin/bash
gw=$(ip route show default | awk 'NR==1{print $3}')
ping -c1 -W2 -q "$gw" >/dev/null || { echo "BLAD: brama $gw - siec lokalna"; exit 1; }
ping -c1 -W2 -q 1.1.1.1 >/dev/null || { echo "BLAD: 1.1.1.1 - routing/NAT lub blokada ICMP"; exit 2; }
ping -c1 -W2 -q archive.ubuntu.com >/dev/null || { echo "BLAD: nazwa - DNS"; exit 3; }
echo "OK: brama, Internet i DNS dzialaja"
EOF
chmod +x ~/bin/lacznosc.sh
~/bin/lacznosc.sh
